const std = @import("std"); const mem2 = std.mem;
const CF = .{ .hdrz = 64, .skip = @as([]const []const u8, &.{ "host", "content-length", "connection", "accept-encoding", "transfer-encoding", "upgrade", "te", "keep-alive" }), .secr = @as([]const []const u8, &.{ "token", "sig", "signature", "key", "apikey", "api_key", "auth", "access_token", "hmac", "secret", "password", "sessionid" }) };
pub const Hdrz = struct { name: []const u8, valu: []const u8 };
pub const Spec = struct { meth: []const u8 = "GET", urlz: []const u8 = "", hdrs: []const Hdrz = &.{}, body: []const u8 = "" };
fn skipHdrz(name: []const u8) bool { if (name.len == 0 or name[0] == ':') return true; for (CF.skip) |skzz| if (std.ascii.eqlIgnoreCase(skzz, name)) return true; return false; }
fn harzRead(aren: std.mem.Allocator, text: []const u8) !Spec { const valu = std.json.parseFromSliceLeaky(std.json.Value, aren, text, .{ .allocate = .alloc_always }) catch return error.BadSpec; if (valu != .object) return error.BadSpec; const logz = valu.object.get("log") orelse return error.BadSpec; if (logz != .object) return error.BadSpec; const ents = logz.object.get("entries") orelse return error.BadSpec; if (ents != .array or ents.array.items.len == 0) return error.BadSpec; const entr = ents.array.items[0]; if (entr != .object) return error.BadSpec; if (entr.object.get("_securityState")) |sstz| { if (sstz == .string and mem2.eql(u8, sstz.string, "insecure")) return error.PinBypass; } const req2 = entr.object.get("request") orelse return error.BadSpec; if (req2 != .object) return error.BadSpec; var spcz: Spec = .{}; if (req2.object.get("method")) |mthz| { if (mthz == .string) spcz.meth = mthz.string; } const urvz = req2.object.get("url") orelse return error.BadSpec; if (urvz != .string) return error.BadSpec; spcz.urlz = urvz.string; var list: std.ArrayList(Hdrz) = .empty; if (req2.object.get("headers")) |hdsz| { if (hdsz == .array) { for (hdsz.array.items) |hdzz| { if (hdzz != .object or list.items.len >= CF.hdrz) continue; const nmzz = hdzz.object.get("name") orelse continue; const vlzz = hdzz.object.get("value") orelse continue; if (nmzz != .string or vlzz != .string or skipHdrz(nmzz.string)) continue; try list.append(aren, .{ .name = nmzz.string, .valu = vlzz.string }); } } } spcz.hdrs = try list.toOwnedSlice(aren); if (req2.object.get("postData")) |pdzz| { if (pdzz == .object) { if (pdzz.object.get("text")) |txzz| { if (txzz == .string) spcz.body = txzz.string; } } } return spcz; }
fn tok2(aren: std.mem.Allocator, text: []const u8) ![]const []const u8 { var outp: std.ArrayList([]const u8) = .empty; var curr: std.ArrayList(u8) = .empty; var inwz = false; var ind2: usize = 0; while (ind2 < text.len) { const chr2 = text[ind2]; if (chr2 == '\\' and ind2 + 1 < text.len and (text[ind2 + 1] == '\n' or text[ind2 + 1] == '\r')) { ind2 += 2; if (ind2 < text.len and text[ind2 - 1] == '\r' and text[ind2] == '\n') ind2 += 1; continue; } if (std.ascii.isWhitespace(chr2)) { if (inwz) { try outp.append(aren, try curr.toOwnedSlice(aren)); curr = .empty; inwz = false; } ind2 += 1; continue; } inwz = true; if (chr2 == '\'' or (chr2 == '$' and ind2 + 1 < text.len and text[ind2 + 1] == '\'')) { const ansi = chr2 == '$'; ind2 += if (ansi) 2 else 1; while (ind2 < text.len and text[ind2] != '\'') { if (ansi and text[ind2] == '\\' and ind2 + 1 < text.len) { ind2 += 1; switch (text[ind2]) { 'n' => try curr.append(aren, '\n'), 'r' => try curr.append(aren, '\r'), 't' => try curr.append(aren, '\t'), else => try curr.append(aren, text[ind2]) } ind2 += 1; continue; } try curr.append(aren, text[ind2]); ind2 += 1; } ind2 += 1; continue; } if (chr2 == '"') { ind2 += 1; while (ind2 < text.len and text[ind2] != '"') { if (text[ind2] == '\\' and ind2 + 1 < text.len) { ind2 += 1; } try curr.append(aren, text[ind2]); ind2 += 1; } ind2 += 1; continue; } if (chr2 == '\\' and ind2 + 1 < text.len) { ind2 += 1; } try curr.append(aren, text[ind2]); ind2 += 1; } if (inwz) try outp.append(aren, try curr.toOwnedSlice(aren)); return outp.toOwnedSlice(aren); }
fn curlRead(aren: std.mem.Allocator, text: []const u8) !Spec { const tkzz = try tok2(aren, text); if (tkzz.len < 2 or !mem2.eql(u8, tkzz[0], "curl")) return error.BadSpec; var spcz: Spec = .{}; var list: std.ArrayList(Hdrz) = .empty; var mset = false; var ind2: usize = 1; while (ind2 < tkzz.len) : (ind2 += 1) { const item = tkzz[ind2]; if (mem2.eql(u8, item, "-k") or mem2.eql(u8, item, "--insecure") or mem2.eql(u8, item, "--proxy-insecure") or mem2.eql(u8, item, "--pinnedpubkey")) return error.PinBypass; const isvz = mem2.eql(u8, item, "-H") or mem2.eql(u8, item, "--header") or mem2.eql(u8, item, "-X") or mem2.eql(u8, item, "--request") or mem2.eql(u8, item, "-d") or mem2.eql(u8, item, "--data") or mem2.eql(u8, item, "--data-raw") or mem2.eql(u8, item, "--data-binary") or mem2.eql(u8, item, "-b") or mem2.eql(u8, item, "--cookie") or mem2.eql(u8, item, "-A") or mem2.eql(u8, item, "--user-agent") or mem2.eql(u8, item, "-u") or mem2.eql(u8, item, "-x") or mem2.eql(u8, item, "--proxy") or mem2.eql(u8, item, "-e") or mem2.eql(u8, item, "--referer"); if (isvz) { ind2 += 1; if (ind2 >= tkzz.len) return error.BadSpec; const val2 = tkzz[ind2]; if (mem2.eql(u8, item, "-H") or mem2.eql(u8, item, "--header")) { const colz = mem2.findScalar(u8, val2, ':') orelse return error.BadSpec; const nmzz = mem2.trim(u8, val2[0..colz], " \t"); if (!skipHdrz(nmzz) and list.items.len < CF.hdrz) try list.append(aren, .{ .name = nmzz, .valu = mem2.trim(u8, val2[colz + 1 ..], " \t") }); } else if (mem2.eql(u8, item, "-X") or mem2.eql(u8, item, "--request")) { spcz.meth = val2; mset = true; } else if (mem2.eql(u8, item, "-b") or mem2.eql(u8, item, "--cookie")) { try list.append(aren, .{ .name = "Cookie", .valu = val2 }); } else if (mem2.eql(u8, item, "-A") or mem2.eql(u8, item, "--user-agent")) { try list.append(aren, .{ .name = "User-Agent", .valu = val2 }); } else if (mem2.eql(u8, item, "-e") or mem2.eql(u8, item, "--referer")) { try list.append(aren, .{ .name = "Referer", .valu = val2 }); } else if (mem2.startsWith(u8, item, "-d") or mem2.startsWith(u8, item, "--data")) { spcz.body = val2; } continue; } if (item.len > 0 and item[0] == '-') continue; if (spcz.urlz.len == 0) spcz.urlz = item; } if (spcz.urlz.len == 0) return error.BadSpec; if (spcz.body.len > 0 and !mset) spcz.meth = "POST"; spcz.hdrs = try list.toOwnedSlice(aren); return spcz; }
pub fn specRead(aren: std.mem.Allocator, text: []const u8) !Spec { const trmz = mem2.trim(u8, text, " \t\r\n\xEF\xBB\xBF"); if (trmz.len == 0) return error.BadSpec; if (trmz[0] == '{') return harzRead(aren, trmz); return curlRead(aren, trmz); }
fn paraGetz(parm: []const u8, name: []const u8) ?[]const u8 { var itrz = mem2.splitScalar(u8, parm, '&'); while (itrz.next()) |pair| { const eqpz = mem2.findScalar(u8, pair, '=') orelse continue; if (mem2.eql(u8, pair[0..eqpz], name)) return pair[eqpz + 1 ..]; } return null; }
pub fn fill(aren: std.mem.Allocator, text: []const u8, parm: []const u8) ![]const u8 { var outp: std.ArrayList(u8) = .empty; var ind2: usize = 0; while (ind2 < text.len) { if (text[ind2] == '{') { var jdxz = ind2 + 1; while (jdxz < text.len and (std.ascii.isLower(text[jdxz]) or std.ascii.isDigit(text[jdxz]) or text[jdxz] == '_')) jdxz += 1; if (jdxz > ind2 + 1 and jdxz < text.len and text[jdxz] == '}') { const val2 = paraGetz(parm, text[ind2 + 1 .. jdxz]) orelse return error.BadSpec; try outp.appendSlice(aren, val2); ind2 = jdxz + 1; continue; } } try outp.append(aren, text[ind2]); ind2 += 1; } return outp.toOwnedSlice(aren); }
pub fn specFill(aren: std.mem.Allocator, spcz: Spec, parm: []const u8) !Spec { var out2 = spcz; out2.urlz = try fill(aren, spcz.urlz, parm); out2.body = try fill(aren, spcz.body, parm); const hdzz = try aren.alloc(Hdrz, spcz.hdrs.len); for (spcz.hdrs, 0..) |item, ind3| hdzz[ind3] = .{ .name = item.name, .valu = try fill(aren, item.valu, parm) }; out2.hdrs = hdzz; return out2; }
pub fn urlzSafe(aren: std.mem.Allocator, urlz: []const u8) ![]const u8 { const qixz = mem2.findScalar(u8, urlz, '?') orelse return urlz; var outp: std.ArrayList(u8) = .empty; try outp.appendSlice(aren, urlz[0..qixz]); var first = true; var itrz = mem2.splitScalar(u8, urlz[qixz + 1 ..], '&'); while (itrz.next()) |pair| { const eqpz = mem2.findScalar(u8, pair, '=') orelse pair.len; var secr = false; for (CF.secr) |skzz| { if (std.ascii.eqlIgnoreCase(skzz, pair[0..eqpz])) secr = true; } if (secr) continue; try outp.append(aren, if (first) '?' else '&'); first = false; try outp.appendSlice(aren, pair); } return outp.toOwnedSlice(aren); }
